#include <stdio.h>
typedef struct Axis6W9Row { unsigned int lane, epoch, handoff; int delta; } Axis6W9Row;
typedef struct Axis6W9Agg { unsigned int epoch[5], handoff[5]; int value[5]; } Axis6W9Agg;
static unsigned int mix9(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear9(Axis6W9Agg* a){ for(int i=0;i<5;++i){ a->epoch[i]=0u; a->handoff[i]=0u; a->value[i]=0; } }
static void absorb9(Axis6W9Agg* a,const Axis6W9Row* r){ unsigned int lane=r->lane%5u; if(r->epoch<a->epoch[lane]) return; if(r->epoch>a->epoch[lane]){ a->epoch[lane]=r->epoch; a->handoff[lane]=r->handoff; a->value[lane]=r->delta; return; } if(r->handoff>a->handoff[lane]){ a->handoff[lane]=r->handoff; a->value[lane]=r->delta; } else if(r->handoff==a->handoff[lane]) a->value[lane]+=r->delta; }
static unsigned int sig9(const Axis6W9Agg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<5u; ++lane){ h=mix9(h,lane+1u); h=mix9(h,a->epoch[lane]); h=mix9(h,a->handoff[lane]); h=mix9(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W9Row rows[]={{0u,2u,1u,4},{1u,3u,2u,5},{2u,1u,3u,7},{3u,2u,4u,3},{4u,1u,2u,6},{0u,5u,2u,6},{1u,4u,3u,-1},{2u,5u,2u,8},{3u,4u,5u,2},{4u,5u,3u,4},{0u,5u,2u,-2},{1u,4u,3u,4},{2u,5u,4u,1},{3u,4u,5u,-3},{4u,5u,3u,-1},{0u,6u,4u,5},{1u,6u,5u,3},{2u,6u,4u,6},{3u,6u,6u,1},{4u,6u,2u,2}}; Axis6W9Agg d,g; clear9(&d); for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i) absorb9(&d,&rows[i]); clear9(&g); for(unsigned int epoch=1u; epoch<=6u; ++epoch) for(unsigned int handoff=1u; handoff<=6u; ++handoff) for(unsigned int lane=0; lane<5u; ++lane){ int merged=0,saw=0; for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ if(rows[i].lane%5u!=lane || rows[i].epoch!=epoch || rows[i].handoff!=handoff) continue; merged+=rows[i].delta; saw=1; } if(saw){ Axis6W9Row row={lane,epoch,handoff,merged}; absorb9(&g,&row); } } { unsigned int sd=sig9(&d), sg=sig9(&g); printf("%u %u %u\n", sd, sg, (sd==sg)?1u:0u); } return 0; }
